void fragment() {
	vec4 src = texture(screen_texture, SCREEN_UV);

	// Bypass: pass through cool-hued pixels (editor collision debug overlays).
	// AXEL palette is strictly warm (red/black/white) so any pixel where
	// min(green, blue) clearly exceeds red is a debug overlay, not game art.
	float cool = min(src.g, src.b) - src.r;
	if (cool > 0.04) {
		COLOR = src;
		return;
	}

	float lum = dot(src.rgb, vec3(0.299, 0.587, 0.114));
	vec4 mapped = black_color;

	if (lum < t0) {
		mapped = black_color;
	} else if (lum < t1) {
		mapped = dark_blood_color;
	} else if (lum < t2) {
		mapped = blood_red_color;
	} else {
		mapped = white_color;
	}

	COLOR = vec4(mapped.rgb, src.a);
}

